// Simple Asteroid Dodge game
// Canvas element with id "game" must exist in the HTML

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');

  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  // Ship definition
  const ship = {
    width: 30,
    height: 30,
    x: canvas.width / 2,
    y: canvas.height - 60,
    speed: 5,
    fuel: 100,
    color: '#00f',
  };

  const keys = { left: false, right: false };
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = true;
    if (e.key === 'ArrowRight' || e.key === 'd') keys.right = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = false;
    if (e.key === 'ArrowRight' || e.key === 'd') keys.right = false;
  });

  const asteroids = [];
  const fuels = [];
  let frame = 0;
  let gameOver = false;

  const spawnAsteroid = () => {
    const size = Math.random() * 30 + 15;
    asteroids.push({
      x: Math.random() * (canvas.width - size),
      y: -size,
      r: size,
      speed: Math.random() * 2 + 1,
    });
  };

  const spawnFuel = () => {
    const size = 10;
    fuels.push({
      x: Math.random() * (canvas.width - size),
      y: -size,
      r: size,
      speed: 1.5,
    });
  };

  const update = () => {
    if (gameOver) return;
    // Move ship
    if (keys.left) ship.x = Math.max(0, ship.x - ship.speed);
    if (keys.right) ship.x = Math.min(canvas.width - ship.width, ship.x + ship.speed);

    // Fuel consumption
    ship.fuel -= 0.05;
    if (ship.fuel <= 0) endGame('Out of fuel');

    // Spawn asteroids every 60 frames
    if (frame % 60 === 0) spawnAsteroid();
    // Spawn fuel pickups every 300 frames
    if (frame % 300 === 0) spawnFuel();

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Remove off‑screen
      if (a.y - a.r > canvas.height) asteroids.splice(i, 1);
      // Collision with ship
      const shipCenterX = ship.x + ship.width / 2;
      const shipCenterY = ship.y + ship.height / 2;
      const dx = a.x - shipCenterX;
      const dy = a.y - shipCenterY;
      if (Math.hypot(dx, dy) < a.r + Math.max(ship.width, ship.height) / 2) {
        endGame('Hit an asteroid');
        return;
      }
    }

    // Update fuel pickups
    for (let i = fuels.length - 1; i >= 0; i--) {
      const f = fuels[i];
      f.y += f.speed;
      if (f.y - f.r > canvas.height) {
        fuels.splice(i, 1);
        continue;
      }
      const shipCenterX = ship.x + ship.width / 2;
      const shipCenterY = ship.y + ship.height / 2;
      const dx = f.x - shipCenterX;
      const dy = f.y - shipCenterY;
      if (Math.hypot(dx, dy) < f.r + Math.max(ship.width, ship.height) / 2) {
        ship.fuel = Math.min(100, ship.fuel + 30);
        fuels.splice(i, 1);
      }
    }
    frame++;
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.width, ship.height);
    // Asteroids
    ctx.fillStyle = '#555';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Fuel pickups
    ctx.fillStyle = '#0f0';
    fuels.forEach(f => {
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Fuel bar
    ctx.fillStyle = '#ff0';
    ctx.fillRect(10, 10, ship.fuel * 2, 10);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, 200, 10);
  };

  const endGame = msg => {
    gameOver = true;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.font = '24px sans-serif';
    ctx.fillText(msg, canvas.width / 2, canvas.height / 2 + 20);
  };

  const loop = () => {
    if (!gameOver) {
      update();
      draw();
    }
    requestAnimationFrame(loop);
  };
  loop();
})();
